	knownrebecs {
		Client client1;
		Client client2;
	}
	statevars {
		int count;
		Client senderTmp;
	}

	Counter() {
		count = 0;
	}

	msgsrv initial() {
		// no automatic behavior
	}

	msgsrv Increment(Client senderRef) {
		count = count + 1;
		senderTmp = senderRef;
		senderTmp.ValueResponse(count);
	}

	msgsrv Decrement(Client senderRef) {
		count = count - 1;
		senderTmp = senderRef;
		senderTmp.ValueResponse(count);
	}

	msgsrv GetValue(Client senderRef) {
		senderTmp = senderRef;
		senderTmp.ValueResponse(count);
	}
}

